/* Run 7 / RDS / five numeric fields / year 2018: plan investigation only.
   Generated from modules/12_numeric_outliers.sql by check_outliers.mjs.
   Replace ALL DQ_DB tokens (including quoted strings) with LAB_T_ORION_MVT.
   Use one fresh SQL Assistant session and submit sections separately.
   No DBQL, catalog SELECT, new procedure, configuration load or engine CALL.
   A is read-only: it MUST return zero rows. Stop on any mismatch or error.
   B copies the current full source population for five fields ONCE into a
   partitioned permanent diagnostic table. It consumes permanent space and
   source-view spool; it does not recreate the historical source snapshot.
   C reads saved aggregate statistics only. D EXPLAIN does NOT execute counting.
   Existing configuration, run logs, rules and results are never modified.
   Verify DQ_DIAG_OUT_R7 is unused. If CREATE fails, stop; do not proceed to DROP.
   If disconnected after B, only the permanent DQ_DIAG_OUT_R7 remains.
   Keep it isolated from normal runs and remove it with E after saving the plan. */

/* A: Check saved run metadata. Expected: ZERO rows. Do this first. */
SELECT 'Run 7 source, status or reporting scope differs' AS ISSUE
FROM DQ_DB.DQ_RUN_LOG L JOIN DQ_DB.DQ_RUN_NUMBER N ON L.RUN_ID=N.RUN_ID
WHERE L.RUN_ID='3b807c69-1596-7a40-b091-17f815617580' AND N.RUN_NUMBER=7 AND L.PROJECT_ID='RDS'
  AND L.STATUS='SUCCEEDED' AND UPPER(L.SOURCE_DATABASE)='DQ_DB'
  AND UPPER(L.SOURCE_TABLE)='VW_RDS_PHASE2_FACT' AND UPPER(L.REPORTING_DATE_FIELD)='FACT_DT'
  AND L.PROFILE_OVERALL='Y' AND L.PROFILE_MONTHLY='Y' AND L.PROFILE_YEARLY='N'
HAVING COUNT(*)<>1
UNION ALL
SELECT 'Numeric field names or ordinals differ' AS ISSUE
FROM DQ_DB.DQ_RUN_FIELD_CONFIG
WHERE RUN_ID='3b807c69-1596-7a40-b091-17f815617580' AND FIELD_TYPE='NUMERIC'
HAVING COUNT(*)<>5 OR SUM(CASE WHEN (FIELD_ORDINAL=1 AND FIELD_NAME='ARREARS_AMT') OR (FIELD_ORDINAL=2 AND FIELD_NAME='ARREARS_AVG_L6M_AMT') OR (FIELD_ORDINAL=3 AND FIELD_NAME='ARREARS_AVG_L7_12M_AMT') OR (FIELD_ORDINAL=4 AND FIELD_NAME='BALANCE_AMT') OR (FIELD_ORDINAL=5 AND FIELD_NAME='MAX_ARREARS_AMT_L6M') THEN 0 ELSE 1 END)<>0
UNION ALL
SELECT 'Captured numeric specials differ' AS ISSUE
FROM DQ_DB.DQ_RUN_SPECIAL_VALUE
WHERE RUN_ID='3b807c69-1596-7a40-b091-17f815617580' AND FIELD_TYPE='NUMERIC'
HAVING COUNT(DISTINCT NUMERIC_VALUE)<>21
    OR SUM(CASE WHEN NUMERIC_VALUE IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.0000000000,-9999.0000000000,-9998.0000000000,-999997.0000000000,-999993.0000000000,-999.0000000000,-999995.0000000000,999999.0000000000,999998.0000000000,999990.0000000000,99999.0000000000,99998.0000000000,999.9900000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN 0 ELSE 1 END)<>0
UNION ALL
SELECT 'Saved overall or 2018 monthly statistics are missing' AS ISSUE
FROM DQ_DB.DQ_RUN_FIELD_CONFIG F
WHERE F.RUN_ID='3b807c69-1596-7a40-b091-17f815617580' AND F.FIELD_TYPE='NUMERIC'
  AND (NOT EXISTS (SELECT 1 FROM DQ_DB.DQ_NUMERIC_STATISTICS S
        WHERE S.RUN_ID=F.RUN_ID AND S.FIELD_NAME=F.FIELD_NAME AND S.PERIOD_LEVEL='OVERALL' AND S.PERIOD_VALUE='ALL')
    OR NOT EXISTS (SELECT 1 FROM DQ_DB.DQ_NUMERIC_STATISTICS S
        WHERE S.RUN_ID=F.RUN_ID AND S.FIELD_NAME=F.FIELD_NAME AND S.PERIOD_LEVEL='MONTHLY' AND S.PERIOD_VALUE LIKE '2018-%'));

/* B: Recreate the same physical stage, with a diagnostic-only name.
   This scans RDS once; record its elapsed minutes from SQL Assistant. */
CREATE MULTISET TABLE DQ_DB.DQ_DIAG_OUT_R7 AS (SELECT "FACT_DT","ARREARS_AMT","ARREARS_AVG_L6M_AMT","ARREARS_AVG_L7_12M_AMT","BALANCE_AMT","MAX_ARREARS_AMT_L6M",RANDOM(1,2147483647) AS "DQ_OS_BUCKET_0",COALESCE(EXTRACT(YEAR FROM "FACT_DT"),0) AS "DQ_OS_YEAR_0" FROM "DQ_DB"."VW_RDS_PHASE2_FACT") WITH DATA PRIMARY INDEX ("DQ_OS_BUCKET_0") PARTITION BY RANGE_N("DQ_OS_YEAR_0" BETWEEN 0 AND 9999 EACH 1);
COLLECT STATISTICS COLUMN (PARTITION), COLUMN ("DQ_OS_YEAR_0") ON DQ_DB.DQ_DIAG_OUT_R7;

/* C: Recreate this batch's saved bounds in this session. No source scan. */
CREATE VOLATILE TABLE DQ_DIAG_OUT_BOUNDS AS (SELECT PERIOD_LEVEL,PERIOD_VALUE,MAX(TOTAL_COUNT) AS TOTAL_N,MAX(CASE WHEN FIELD_NAME='ARREARS_AMT' THEN VALID_COUNT END) AS N1,MAX(CASE WHEN FIELD_NAME='ARREARS_AMT' THEN LB END) AS L1,MAX(CASE WHEN FIELD_NAME='ARREARS_AMT' THEN UB END) AS U1,MAX(CASE WHEN FIELD_NAME='ARREARS_AVG_L6M_AMT' THEN VALID_COUNT END) AS N2,MAX(CASE WHEN FIELD_NAME='ARREARS_AVG_L6M_AMT' THEN LB END) AS L2,MAX(CASE WHEN FIELD_NAME='ARREARS_AVG_L6M_AMT' THEN UB END) AS U2,MAX(CASE WHEN FIELD_NAME='ARREARS_AVG_L7_12M_AMT' THEN VALID_COUNT END) AS N3,MAX(CASE WHEN FIELD_NAME='ARREARS_AVG_L7_12M_AMT' THEN LB END) AS L3,MAX(CASE WHEN FIELD_NAME='ARREARS_AVG_L7_12M_AMT' THEN UB END) AS U3,MAX(CASE WHEN FIELD_NAME='BALANCE_AMT' THEN VALID_COUNT END) AS N4,MAX(CASE WHEN FIELD_NAME='BALANCE_AMT' THEN LB END) AS L4,MAX(CASE WHEN FIELD_NAME='BALANCE_AMT' THEN UB END) AS U4,MAX(CASE WHEN FIELD_NAME='MAX_ARREARS_AMT_L6M' THEN VALID_COUNT END) AS N5,MAX(CASE WHEN FIELD_NAME='MAX_ARREARS_AMT_L6M' THEN LB END) AS L5,MAX(CASE WHEN FIELD_NAME='MAX_ARREARS_AMT_L6M' THEN UB END) AS U5 FROM (SELECT S.*,CASE WHEN VALID_COUNT>=1 AND STDDEV_VALUE IS NOT NULL THEN MEAN_VALUE-3.0*STDDEV_VALUE END AS LB,CASE WHEN VALID_COUNT>=1 AND STDDEV_VALUE IS NOT NULL THEN MEAN_VALUE+3.0*STDDEV_VALUE END AS UB FROM DQ_DB.DQ_NUMERIC_STATISTICS S WHERE RUN_ID='3b807c69-1596-7a40-b091-17f815617580' AND FIELD_NAME IN (SELECT FIELD_NAME FROM DQ_DB.DQ_RUN_FIELD_CONFIG WHERE RUN_ID='3b807c69-1596-7a40-b091-17f815617580' AND FIELD_TYPE='NUMERIC' AND FIELD_ORDINAL BETWEEN 1 AND 5)) Q GROUP BY PERIOD_LEVEL,PERIOD_VALUE) WITH DATA PRIMARY INDEX (PERIOD_LEVEL,PERIOD_VALUE) ON COMMIT PRESERVE ROWS;

/* D: Paste the complete EXPLAIN output for review. Keep EXPLAIN in place;
   this investigates one real count-query shape without executing it. */
EXPLAIN
SELECT CAST(CASE WHEN '2018'='ALL' THEN 'ALL' WHEN '2018'='UNKNOWN' THEN 'UNKNOWN' ELSE CAST('2018-'||SUBSTR('00'||TRIM(CAST(EXTRACT(MONTH FROM S.DQ_DT) AS VARCHAR(2))),CHARACTER_LENGTH('00'||TRIM(CAST(EXTRACT(MONTH FROM S.DQ_DT) AS VARCHAR(2))))-1,2) AS VARCHAR(7)) END AS VARCHAR(10)) AS CHUNK_VALUE,CAST('2018' AS VARCHAR(10)) AS CHUNK_YEAR,MAX(B0.TOTAL_N) AS OVERALL_TOTAL_N,CAST(NULL AS BIGINT) AS YEARLY_TOTAL_N,MAX(BM.TOTAL_N) AS MONTHLY_TOTAL_N,COALESCE(SUM(CAST(CASE WHEN S.DQ_PRESENT=1 THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL_TOTAL,MAX(B0.N1) AS ON1,MAX(B0.L1) AS OL1,MAX(B0.U1) AS OU1,CAST(NULL AS BIGINT) AS YN1,CAST(NULL AS FLOAT) AS YL1,CAST(NULL AS FLOAT) AS YU1,MAX(BM.N1) AS MN1,MAX(BM.L1) AS ML1,MAX(BM.U1) AS MU1,COALESCE(SUM(CAST(CASE WHEN S.DQ_C1 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL1,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C1 AS FLOAT)<B0.L1 OR CAST(S.DQ_C1 AS FLOAT)>B0.U1) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO1,CAST(0 AS BIGINT) AS YO1,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C1 AS FLOAT)<BM.L1 OR CAST(S.DQ_C1 AS FLOAT)>BM.U1) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO1,MAX(B0.N2) AS ON2,MAX(B0.L2) AS OL2,MAX(B0.U2) AS OU2,CAST(NULL AS BIGINT) AS YN2,CAST(NULL AS FLOAT) AS YL2,CAST(NULL AS FLOAT) AS YU2,MAX(BM.N2) AS MN2,MAX(BM.L2) AS ML2,MAX(BM.U2) AS MU2,COALESCE(SUM(CAST(CASE WHEN S.DQ_C2 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL2,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C2 AS FLOAT)<B0.L2 OR CAST(S.DQ_C2 AS FLOAT)>B0.U2) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO2,CAST(0 AS BIGINT) AS YO2,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C2 AS FLOAT)<BM.L2 OR CAST(S.DQ_C2 AS FLOAT)>BM.U2) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO2,MAX(B0.N3) AS ON3,MAX(B0.L3) AS OL3,MAX(B0.U3) AS OU3,CAST(NULL AS BIGINT) AS YN3,CAST(NULL AS FLOAT) AS YL3,CAST(NULL AS FLOAT) AS YU3,MAX(BM.N3) AS MN3,MAX(BM.L3) AS ML3,MAX(BM.U3) AS MU3,COALESCE(SUM(CAST(CASE WHEN S.DQ_C3 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL3,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C3 AS FLOAT)<B0.L3 OR CAST(S.DQ_C3 AS FLOAT)>B0.U3) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO3,CAST(0 AS BIGINT) AS YO3,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C3 AS FLOAT)<BM.L3 OR CAST(S.DQ_C3 AS FLOAT)>BM.U3) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO3,MAX(B0.N4) AS ON4,MAX(B0.L4) AS OL4,MAX(B0.U4) AS OU4,CAST(NULL AS BIGINT) AS YN4,CAST(NULL AS FLOAT) AS YL4,CAST(NULL AS FLOAT) AS YU4,MAX(BM.N4) AS MN4,MAX(BM.L4) AS ML4,MAX(BM.U4) AS MU4,COALESCE(SUM(CAST(CASE WHEN S.DQ_C4 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL4,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C4 AS FLOAT)<B0.L4 OR CAST(S.DQ_C4 AS FLOAT)>B0.U4) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO4,CAST(0 AS BIGINT) AS YO4,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C4 AS FLOAT)<BM.L4 OR CAST(S.DQ_C4 AS FLOAT)>BM.U4) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO4,MAX(B0.N5) AS ON5,MAX(B0.L5) AS OL5,MAX(B0.U5) AS OU5,CAST(NULL AS BIGINT) AS YN5,CAST(NULL AS FLOAT) AS YL5,CAST(NULL AS FLOAT) AS YU5,MAX(BM.N5) AS MN5,MAX(BM.L5) AS ML5,MAX(BM.U5) AS MU5,COALESCE(SUM(CAST(CASE WHEN S.DQ_C5 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL5,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C5 AS FLOAT)<B0.L5 OR CAST(S.DQ_C5 AS FLOAT)>B0.U5) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO5,CAST(0 AS BIGINT) AS YO5,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C5 AS FLOAT)<BM.L5 OR CAST(S.DQ_C5 AS FLOAT)>BM.U5) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO5 FROM (SELECT MAX(TOTAL_N) AS TOTAL_N,MAX(N1) AS N1,MAX(L1) AS L1,MAX(U1) AS U1,MAX(N2) AS N2,MAX(L2) AS L2,MAX(U2) AS U2,MAX(N3) AS N3,MAX(L3) AS L3,MAX(U3) AS U3,MAX(N4) AS N4,MAX(L4) AS L4,MAX(U4) AS U4,MAX(N5) AS N5,MAX(L5) AS L5,MAX(U5) AS U5 FROM DQ_DIAG_OUT_BOUNDS WHERE PERIOD_LEVEL='OVERALL' AND PERIOD_VALUE='ALL') B0 LEFT JOIN (SELECT "FACT_DT" AS DQ_DT,1 AS DQ_PRESENT,CASE WHEN "ARREARS_AMT" IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.0000000000,-9999.0000000000,-9998.0000000000,-999997.0000000000,-999993.0000000000,-999.0000000000,-999995.0000000000,999999.0000000000,999998.0000000000,999990.0000000000,99999.0000000000,99998.0000000000,999.9900000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN NULL ELSE "ARREARS_AMT" END AS DQ_C1,CASE WHEN "ARREARS_AVG_L6M_AMT" IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.0000000000,-9999.0000000000,-9998.0000000000,-999997.0000000000,-999993.0000000000,-999.0000000000,-999995.0000000000,999999.0000000000,999998.0000000000,999990.0000000000,99999.0000000000,99998.0000000000,999.9900000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN NULL ELSE "ARREARS_AVG_L6M_AMT" END AS DQ_C2,CASE WHEN "ARREARS_AVG_L7_12M_AMT" IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.0000000000,-9999.0000000000,-9998.0000000000,-999997.0000000000,-999993.0000000000,-999.0000000000,-999995.0000000000,999999.0000000000,999998.0000000000,999990.0000000000,99999.0000000000,99998.0000000000,999.9900000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN NULL ELSE "ARREARS_AVG_L7_12M_AMT" END AS DQ_C3,CASE WHEN "BALANCE_AMT" IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.0000000000,-9999.0000000000,-9998.0000000000,-999997.0000000000,-999993.0000000000,-999.0000000000,-999995.0000000000,999999.0000000000,999998.0000000000,999990.0000000000,99999.0000000000,99998.0000000000,999.9900000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN NULL ELSE "BALANCE_AMT" END AS DQ_C4,CASE WHEN "MAX_ARREARS_AMT_L6M" IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.0000000000,-9999.0000000000,-9998.0000000000,-999997.0000000000,-999993.0000000000,-999.0000000000,-999995.0000000000,999999.0000000000,999998.0000000000,999990.0000000000,99999.0000000000,99998.0000000000,999.9900000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN NULL ELSE "MAX_ARREARS_AMT_L6M" END AS DQ_C5 FROM "DQ_DB"."DQ_DIAG_OUT_R7" WHERE "DQ_OS_YEAR_0"=2018) S ON 1=1 LEFT JOIN DQ_DIAG_OUT_BOUNDS BM ON 'Y'='Y' AND BM.PERIOD_LEVEL='MONTHLY' AND BM.PERIOD_VALUE=CASE WHEN S.DQ_DT IS NULL THEN 'UNKNOWN' ELSE CAST('2018-'||SUBSTR('00'||TRIM(CAST(EXTRACT(MONTH FROM S.DQ_DT) AS VARCHAR(2))),CHARACTER_LENGTH('00'||TRIM(CAST(EXTRACT(MONTH FROM S.DQ_DT) AS VARCHAR(2))))-1,2) AS VARCHAR(7)) END GROUP BY EXTRACT(MONTH FROM S.DQ_DT);

/* D2: NONEMPTY 2018 chunk only. Run ONLY this EXPLAIN if A-D already succeeded
   in this session. Reuses the same stage and bounds: no table recreation and
   no engine changes. Compare with D: does the detail redistribution on constant
