) AS ACTUAL3,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C3 AS FLOAT)<B0.L3 OR CAST(S.DQ_C3 AS FLOAT)>B0.U3) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO3,CAST(0 AS BIGINT) AS YO3,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C3 AS FLOAT)<BM.L3 OR CAST(S.DQ_C3 AS FLOAT)>BM.U3) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO3,MAX(B0.N4) AS ON4,MAX(B0.L4) AS OL4,MAX(B0.U4) AS OU4,CAST(NULL AS BIGINT) AS YN4,CAST(NULL AS FLOAT) AS YL4,CAST(NULL AS FLOAT) AS YU4,MAX(BM.N4) AS MN4,MAX(BM.L4) AS ML4,MAX(BM.U4) AS MU4,COALESCE(SUM(CAST(CASE WHEN S.DQ_C4 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL4,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C4 AS FLOAT)<B0.L4 OR CAST(S.DQ_C4 AS FLOAT)>B0.U4) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO4,CAST(0 AS BIGINT) AS YO4,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C4 AS FLOAT)<BM.L4 OR CAST(S.DQ_C4 AS FLOAT)>BM.U4) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO4,MAX(B0.N5) AS ON5,MAX(B0.L5) AS OL5,MAX(B0.U5) AS OU5,CAST(NULL AS BIGINT) AS YN5,CAST(NULL AS FLOAT) AS YL5,CAST(NULL AS FLOAT) AS YU5,MAX(BM.N5) AS MN5,MAX(BM.L5) AS ML5,MAX(BM.U5) AS MU5,COALESCE(SUM(CAST(CASE WHEN S.DQ_C5 IS NOT NULL THEN 1 ELSE 0 END AS BIGINT)),0) AS ACTUAL5,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C5 AS FLOAT)<B0.L5 OR CAST(S.DQ_C5 AS FLOAT)>B0.U5) THEN 1 ELSE 0 END AS BIGINT)),0) AS OO5,CAST(0 AS BIGINT) AS YO5,COALESCE(SUM(CAST(CASE WHEN 'Y'='Y' AND (CAST(S.DQ_C5 AS FLOAT)<BM.L5 OR CAST(S.DQ_C5 AS FLOAT)>BM.U5) THEN 1 ELSE 0 END AS BIGINT)),0) AS MO5 FROM (SELECT MAX(TOTAL_N) AS TOTAL_N,MAX(N1) AS N1,MAX(L1) AS L1,MAX(U1) AS U1,MAX(N2) AS N2,MAX(L2) AS L2,MAX(U2) AS U2,MAX(N3) AS N3,MAX(L3) AS L3,MAX(U3) AS U3,MAX(N4) AS N4,MAX(L4) AS L4,MAX(U4) AS U4,MAX(N5) AS N5,MAX(L5) AS L5,MAX(U5) AS U5 FROM DQ_DIAG_OUT_BOUNDS WHERE PERIOD_LEVEL='OVERALL' AND PERIOD_VALUE='ALL') B0 CROSS JOIN (SELECT "FACT_DT" AS DQ_DT,1 AS DQ_PRESENT,CASE WHEN "ARREARS_AMT" IN (-99999.0000000000,-999999.0000000000,-999998.0000000000,-99998.0000000000,-99997.