000000,999.8800000000,999.0000000000,9999.0000000000,9998.0000000000) THEN NULL ELSE "MAX_ARREARS_AMT_L6M" END AS DQ_C5 FROM "DQ_DB"."DQ_DIAG_OUT_R7" WHERE "DQ_OS_YEAR_0"=2018) S LEFT JOIN DQ_DIAG_OUT_BOUNDS BM ON 'Y'='Y' AND BM.PERIOD_LEVEL='MONTHLY' AND BM.PERIOD_VALUE=CASE WHEN S.DQ_DT IS NULL THEN 'UNKNOWN' ELSE CAST('2018-'||SUBSTR('00'||TRIM(CAST(EXTRACT(MONTH FROM S.DQ_DT) AS VARCHAR(2))),CHARACTER_LENGTH('00'||TRIM(CAST(EXTRACT(MONTH FROM S.DQ_DT) AS VARCHAR(2))))-1,2) AS VARCHAR(7)) END GROUP BY EXTRACT(MONTH FROM S.DQ_DT);

